-- #787: the US and college soccer leagues: MLS, the NWSL and the NCAA Division I men's and
-- women's tournaments. Each event is a playoff or tournament on a fixed bracket with its own round
-- names. MLS's round one is a best-of-three series, one bracket match scored in games won with no
-- half-time score, so its squares pools start at the conference semifinals (round 3). Idempotent
-- on the (sport_id, name) unique: an admin who already created a league keeps their row.
INSERT INTO "sport_leagues" ("id", "sport_id", "name", "bracket_advancement", "round_names", "squares_from_round", "is_active", "created_at", "updated_at")
SELECT gen_random_uuid(), s."id", league."name", 'FIXED', league."round_names", league."squares_from_round", TRUE, NOW(), NOW()
FROM "sports" s
CROSS JOIN (VALUES
  ('MLS', ARRAY['Wild Card', 'Round One', 'Conference Semifinals', 'Conference Finals', 'MLS Cup']::text[], 3),
  ('NWSL', ARRAY['Quarterfinals', 'Semifinals', 'Championship']::text[], NULL::int),
  ('NCAA Division I Men', ARRAY['First Round', 'Second Round', 'Round of 16', 'Quarterfinals', 'Semifinals', 'Final']::text[], NULL::int),
  ('NCAA Division I Women', ARRAY['First Round', 'Second Round', 'Round of 16', 'Quarterfinals', 'Semifinals', 'Final']::text[], NULL::int)
) AS league("name", "round_names", "squares_from_round")
WHERE s."sport" = 'SOCCER'
ON CONFLICT ("sport_id", "name") DO UPDATE SET "round_names" = EXCLUDED."round_names", "squares_from_round" = EXCLUDED."squares_from_round";

-- Each league's contest templates, as soccer's other leagues have them (`rules/ux-rules.md` §12):
-- one default per format, ahead of its variations, all for a KNOCKOUT, with round values doubling
-- to the league's last round.
INSERT INTO "contest_config_templates" (
  "id", "sport", "sport_league_id", "event_type", "contest_type", "selection_type", "template_key",
  "name", "description", "sort_order", "is_default", "active", "config_json", "schema_version", "updated_at"
)
SELECT
  gen_random_uuid(), 'SOCCER', l."id", 'KNOCKOUT', preset."contest_type"::"PrismaContestFormat",
  preset."selection_type"::"PrismaSelectionType", preset."template_key", preset."name", preset."description",
  preset."sort_order", preset."is_default", TRUE, preset."config_json"::jsonb, 1, NOW()
FROM (VALUES
  ('MLS', 'TIERED', 'ROSTER', 'mls-tiered-doubling', 'Tiered: 1 team per tier, doubling points', 'Pick one team from each of the four tiers. A win scores 1 point in the wild card round, doubling each round to 16 in MLS Cup.', 1, TRUE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16], "upsetBonus": {"rule": "NONE"}}}}'),
  ('MLS', 'BUDGET_PICK', 'ROSTER', 'mls-budget-doubling', 'Budget: 4 teams under the cap, doubling points', 'Every team has a price: pick four whose prices fit under the salary cap. A win scores 1 point in the wild card round, doubling each round to 16 in MLS Cup.', 3, TRUE, '{"selectionType": "BUDGET_PICK", "rosterSize": 4, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16], "upsetBonus": {"rule": "NONE"}}}}'),
  ('MLS', 'RANDOM_DRAW', 'ROSTER', 'mls-random-draw-doubling', 'Random draw: 1 team each, doubling points', 'The sweepstake: the draw deals each entry one team at random. A win scores 1 point in the wild card round, doubling each round to 16 in MLS Cup.', 5, TRUE, '{"selectionType": "RANDOM_DRAW", "picksPerEntry": 1, "countedScores": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16], "upsetBonus": {"rule": "NONE"}}}}'),
  ('MLS', 'BRACKET', 'PREDICTION', 'mls-bracket-doubling', 'Bracket: full bracket, doubling points', 'Pick the winner of every match to the final before the first one starts. A right pick scores 1 point in the wild card round, doubling each round to 16 in MLS Cup.', 7, TRUE, '{"selectionType": "BRACKET", "startsAtRound": 1, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16], "upsetBonus": {"rule": "NONE"}}}}'),
  ('MLS', 'TIERED', 'ROSTER', 'mls-tiered-doubling-upset-bonus', 'Tiered: 1 team per tier, doubling + upset bonus', 'Pick one team from each of the four tiers. A win scores 1 point in the wild card round, doubling each round to 16 in MLS Cup, plus the seed difference for an upset.', 2, FALSE, '{"selectionType": "TIERED", "picksPerTier": 1, "countedScores": 4, "maxEntriesPerSquad": 1, "scoring": {"participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS", "config": {"roundValues": [1, 2, 4, 8, 16], "upsetBonus": {"rule": "SEED_DIFFERENCE", "multiplier": 1}}}}'),
