  ('NCAA Division I Women', 'SQUARES', 'SQUARES', 'ncaa-women-soccer-squares', 'Squares: 10 boxes each, every half', 'A 10x10 grid on one match: claim up to 10 boxes, then the digits are drawn. The box matching each team''s last digit wins at half time and on the final score.', 10, TRUE, '{"selectionType": "SQUARES", "maxSquaresPerEntry": 10, "maxEntriesPerSquad": 1}'),
  ('NCAA Division I Women', 'SURVIVOR', 'PREDICTION', 'ncaa-women-soccer-knockout-survivor', 'Survivor: 1 team a round, each team once', 'Pick one team to win in each round, never the same team twice. A loss puts the entry out; the last ones standing win.', 11, TRUE, '{"selectionType": "SURVIVOR", "maxEntriesPerSquad": 1}')
) AS preset("league", "selection_type", "contest_type", "template_key", "name", "description", "sort_order", "is_default", "config_json")
JOIN "sports" s ON s."sport" = 'SOCCER'
JOIN "sport_leagues" l ON l."sport_id" = s."id" AND l."name" = preset."league"
ON CONFLICT ("sport", "event_type", "contest_type", "selection_type", "template_key") DO NOTHING;
